+      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]
+      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]
+  -s, --startingPassword <startingPassword>      password to start from
+  -h, --help                                     Print help
+  -V, --version                                  Print version
+`
+	versionText = "zip-password-finder 0.10.3"
+)
+
+var (
+	errMissingEOCD       = errors.New("invalid Zip archive: Could not find EOCD")
+	errUnsupportedMethod = errors.New("invalid Zip archive: unsupported compression method")
+)
+
+type config struct {
+	inputFile          string
+	workers            int
+	passwordDictionary string
+	charset            string
+	charsetFile        string
+	minPasswordLen     int
+	maxPasswordLen     int
+	fileNumber         int
+	startingPassword   string
+	showHelp           bool
+	showVersion        bool
+}
+
+type zipArchive struct {
+	data    []byte
+	entries []zipEntry
+}
+
+type zipEntry struct {
+	filename             string
+	flags                uint16
+	modTime              uint16
+	compressionMethod    uint16
+	actualCompression    uint16
+	crc32                uint32
+	compressedSize       uint32
+	uncompressedSize     uint32
+	localHeaderOffset    uint32
+	dataOffset           uint64
+	encrypted            bool
+	aes                  *aesInfo
+}
+
+type aesInfo struct {
+	version           uint16
+	strength          uint8
+	actualCompression uint16
+	saltLen           int
+	keyLen            int
+}
+
+type passwordChecker struct {
+	data  []byte
+	entry zipEntry
+}
+
+type parseFailure struct {
+	message string
+	code    int
+}
+
+func main() {
+	cfg, failure := parseArgs(os.Args[1:])
+	if failure != nil {
+		printFailure(*failure)
+		os.Exit(failure.code)
+	}
+
+	if cfg.showHelp {
+		fmt.Print(helpText)
+		return
+	}
+	if cfg.showVersion {
+		fmt.Println(versionText)
+		return
+	}
+
+	if err := validateConfig(&cfg); err != nil {
+		fmt.Fprintln(os.Stderr, err.Error())
+		os.Exit(1)
+	}
+
+	archive, err := parseZipArchive(cfg.inputFile)
+	if err != nil {
+		fmt.Fprintf(os.Stderr, "Invalid zip file error - %s\n", err.Error())
+		os.Exit(1)
+	}
+
+	if cfg.fileNumber < 0 || cfg.fileNumber >= len(archive.entries) {
+		fmt.Fprintf(os.Stderr, "File number not found within archive error - '%d'\n", cfg.fileNumber)
+		os.Exit(1)
+	}
+
+	entry := archive.entries[cfg.fileNumber]
+	if !entry.encrypted {
+		fmt.Fprintf(
+			os.Stderr,
+			"Invalid zip file error - the selected file in the archive is not encrypted (file_number:%d file_name:%s)\n",
+			cfg.fileNumber,
+			entry.filename,
+		)
+		os.Exit(1)
+	}
+
+	charset, err := resolveCharset(cfg)
