+
+	if err := validateStartingPassword(cfg, charset); err != nil {
+		fmt.Fprintf(os.Stderr, "CLI argument error - %q\n", err.Error())
+		os.Exit(1)
+	}
+
+	checker := passwordChecker{data: archive.data, entry: entry}
+	startedAt := time.Now()
+
+	var password string
+	var found bool
+	if cfg.passwordDictionary != "" {
+		password, found = dictionaryAttack(checker, cfg.passwordDictionary)
+	} else {
+		password, found = bruteForceAttack(checker, charset, cfg.minPasswordLen, cfg.maxPasswordLen, cfg.startingPassword, cfg.workers)
+	}
+
+	fmt.Printf("Time elapsed: %s\n", formatDuration(time.Since(startedAt)))
+	if found {
+		fmt.Printf("Password found:%s\n", password)
