+}
+
+func parseArgs(args []string) (config, *parseFailure) {
+	cfg := config{
+		charset:        "lud",
+		minPasswordLen: 1,
+		maxPasswordLen: 10,
+		fileNumber:     0,
+		workers:        defaultWorkers(),
+	}
+
+	for i := 0; i < len(args); i++ {
+		arg := args[i]
+		switch {
+		case arg == "-h" || arg == "--help":
+			cfg.showHelp = true
+		case arg == "-V" || arg == "--version":
+			cfg.showVersion = true
+		case arg == "-i" || arg == "--inputFile":
+			value, next, failure := requireValue(args, i, arg, "inputFile")
+			if failure != nil {
+				return config{}, failure
+			}
+			cfg.inputFile = value
+			i = next
+		case strings.HasPrefix(arg, "--inputFile="):
+			cfg.inputFile = strings.TrimPrefix(arg, "--inputFile=")
+		case arg == "-w" || arg == "--workers":
+			value, next, failure := requireValue(args, i, arg, "workers")
+			if failure != nil {
+				return config{}, failure
+			}
+			parsed, parseErr := parseUnsignedValue(value, "--workers <workers>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.workers = parsed
+			i = next
+		case strings.HasPrefix(arg, "--workers="):
+			value := strings.TrimPrefix(arg, "--workers=")
+			parsed, parseErr := parseUnsignedValue(value, "--workers <workers>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.workers = parsed
+		case arg == "-p" || arg == "--passwordDictionary":
+			value, next, failure := requireValue(args, i, arg, "passwordDictionary")
+			if failure != nil {
+				return config{}, failure
+			}
+			cfg.passwordDictionary = value
+			i = next
+		case strings.HasPrefix(arg, "--passwordDictionary="):
+			cfg.passwordDictionary = strings.TrimPrefix(arg, "--passwordDictionary=")
+		case arg == "-c" || arg == "--charset":
+			value, next, failure := requireValue(args, i, arg, "charset")
+			if failure != nil {
+				return config{}, failure
+			}
+			cfg.charset = value
+			i = next
+		case strings.HasPrefix(arg, "--charset="):
+			cfg.charset = strings.TrimPrefix(arg, "--charset=")
+		case arg == "--charsetFile":
+			value, next, failure := requireValue(args, i, arg, "charsetFile")
+			if failure != nil {
+				return config{}, failure
+			}
+			cfg.charsetFile = value
+			i = next
+		case strings.HasPrefix(arg, "--charsetFile="):
+			cfg.charsetFile = strings.TrimPrefix(arg, "--charsetFile=")
+		case arg == "--minPasswordLen":
+			value, next, failure := requireValue(args, i, arg, "minPasswordLen")
+			if failure != nil {
+				return config{}, failure
+			}
+			parsed, parseErr := parseUnsignedValue(value, "--minPasswordLen <minPasswordLen>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.minPasswordLen = parsed
+			i = next
+		case strings.HasPrefix(arg, "--minPasswordLen="):
+			value := strings.TrimPrefix(arg, "--minPasswordLen=")
+			parsed, parseErr := parseUnsignedValue(value, "--minPasswordLen <minPasswordLen>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.minPasswordLen = parsed
+		case arg == "--maxPasswordLen":
+			value, next, failure := requireValue(args, i, arg, "maxPasswordLen")
+			if failure != nil {
+				return config{}, failure
+			}
+			parsed, parseErr := parseUnsignedValue(value, "--maxPasswordLen <maxPasswordLen>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.maxPasswordLen = parsed
+			i = next
+		case strings.HasPrefix(arg, "--maxPasswordLen="):
+			value := strings.TrimPrefix(arg, "--maxPasswordLen=")
+			parsed, parseErr := parseUnsignedValue(value, "--maxPasswordLen <maxPasswordLen>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.maxPasswordLen = parsed
+		case arg == "--fileNumber":
+			value, next, failure := requireValue(args, i, arg, "fileNumber")
+			if failure != nil {
+				return config{}, failure
+			}
+			parsed, parseErr := parseUnsignedValue(value, "--fileNumber <fileNumber>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.fileNumber = parsed
+			i = next
+		case strings.HasPrefix(arg, "--fileNumber="):
+			value := strings.TrimPrefix(arg, "--fileNumber=")
+			parsed, parseErr := parseUnsignedValue(value, "--fileNumber <fileNumber>")
+			if parseErr != nil {
+				return config{}, parseErr
+			}
+			cfg.fileNumber = parsed
+		case arg == "-s" || arg == "--startingPassword":
+			value, next, failure := requireValue(args, i, arg, "startingPassword")
+			if failure != nil {
+				return config{}, failure
+			}
+			cfg.startingPassword = value
+			i = next
+		case strings.HasPrefix(arg, "--startingPassword="):
+			cfg.startingPassword = strings.TrimPrefix(arg, "--startingPassword=")
+		default:
+			return config{}, &parseFailure{
+				message: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: executable --inputFile <inputFile>\n\nFor more information, try '--help'.", arg),
+				code:    2,
+			}
+		}
+	}
+
+	if cfg.showHelp || cfg.showVersion {
+		return cfg, nil
+	}
+	if cfg.inputFile == "" {
+		return config{}, &parseFailure{
+			message: "error: the following required arguments were not provided:\n  --inputFile <inputFile>\n\nUsage: executable --inputFile <inputFile>\n\nFor more information, try '--help'.",
+			code:    2,
+		}
+	}
+	return cfg, nil
+}
+
+func requireValue(args []string, currentIndex int, rawArg string, fieldName string) (string, int, *parseFailure) {
+	if currentIndex+1 >= len(args) {
+		return "", currentIndex, &parseFailure{
+			message: fmt.Sprintf("error: a value is required for '%s <%s>' but none was supplied\n\nFor more information, try '--help'.", rawArg, fieldName),
+			code:    2,
+		}
+	}
+	return args[currentIndex+1], currentIndex + 1, nil
+}
+
+func parseUnsignedValue(raw string, flagLabel string) (int, *parseFailure) {
+	if raw == "" {
+		return 0, &parseFailure{
+			message: fmt.Sprintf("error: invalid value '%s' for '%s': invalid digit found in string\n\nFor more information, try '--help'.", raw, flagLabel),
+			code:    2,
+		}
+	}
+	value := 0
+	for _, ch := range raw {
+		if ch < '0' || ch > '9' {
+			return 0, &parseFailure{
+				message: fmt.Sprintf("error: invalid value '%s' for '%s': invalid digit found in string\n\nFor more information, try '--help'.", raw, flagLabel),
+				code:    2,
+			}
+		}
+		value = value*10 + int(ch-'0')
+	}
+	return value, nil
+}
+
+func validateConfig(cfg *config) error {
+	if _, err := os.Stat(cfg.inputFile); err != nil {
+		return errors.New(`CLI argument error - "'inputFile' does not exist"`)
+	}
+	if cfg.passwordDictionary != "" {
+		if _, err := os.Stat(cfg.passwordDictionary); err != nil {
+			return errors.New(`CLI argument error - "'passwordDictionary' does not exist"`)
+		}
+	}
+	if cfg.charsetFile != "" {
+		if _, err := os.Stat(cfg.charsetFile); err != nil {
+			return errors.New(`CLI argument error - "'charsetFile' does not exist"`)
+		}
+	}
+	if cfg.workers <= 0 {
+		return errors.New(`CLI argument error - "'workers' must be positive"`)
+	}
+	if cfg.minPasswordLen <= 0 {
+		return errors.New(`CLI argument error - "'minPasswordLen' must be positive"`)
+	}
+	if cfg.maxPasswordLen < cfg.minPasswordLen {
+		return errors.New(`CLI argument error - "'maxPasswordLen' must be equal or greater than 'minPasswordLen'"`)
+	}
+	if cfg.passwordDictionary != "" && cfg.startingPassword != "" {
+		return errors.New(`CLI argument error - "'startingPassword' cannot be used with a dictionary file"`)
+	}
+	return nil
+}
+
+func resolveCharset(cfg config) ([]byte, error) {
+	if cfg.charsetFile != "" {
+		data, err := os.ReadFile(cfg.charsetFile)
+		if err != nil {
+			return nil, err
+		}
+		data = bytes.ReplaceAll(data, []byte("\r"), nil)
+		data = bytes.ReplaceAll(data, []byte("\n"), nil)
+		return data, nil
+	}
+
+	var charset []byte
+	for _, opt := range cfg.charset {
+		switch opt {
+		case 'l':
+			charset = append(charset, []byte("abcdefghijklmnopqrstuvwxyz")...)
+		case 'u':
+			charset = append(charset, []byte("ABCDEFGHIJKLMNOPQRSTUVWXYZ")...)
+		case 'd':
+			charset = append(charset, []byte("0123456789")...)
+		case 'h':
+			charset = append(charset, []byte("0123456789abcdef")...)
+		case 'H':
+			charset = append(charset, []byte("0123456789ABCDEF")...)
+		case 's':
+			charset = append(charset, []byte(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")...)
+		default:
+			return nil, fmt.Errorf("Unknown charset option '%c'", opt)
+		}
+	}
+	return charset, nil
+}
+
+func validateStartingPassword(cfg config, charset []byte) error {
+	if cfg.startingPassword == "" {
+		return nil
+	}
+	if len(cfg.startingPassword) < cfg.minPasswordLen || len(cfg.startingPassword) > cfg.maxPasswordLen {
+		return errors.New(`'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration`)
+	}
+	allowed := make(map[byte]struct{}, len(charset))
+	for _, ch := range charset {
+		allowed[ch] = struct{}{}
+	}
+	for i := 0; i < len(cfg.startingPassword); i++ {
+		if _, ok := allowed[cfg.startingPassword[i]]; !ok {
+			return errors.New(`'startingPassword' uses characters out of the generation charset`)
+		}
+	}
+	return nil
+}
+
+func printFailure(failure parseFailure) {
+	if failure.code == 0 {
+		fmt.Println(failure.message)
+		return
+	}
+	fmt.Fprintln(os.Stderr, failure.message)
+}
+
+func defaultWorkers() int {
+	n := runtime.NumCPU() / 2
+	if n <= 0 {
+		return 1
+	}
+	return n
+}
+
+func parseZipArchive(path string) (*zipArchive, error) {
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return nil, err
+	}
+	if len(data) < 22 {
+		return nil, errMissingEOCD
+	}
+
+	eocdOffset := findEOCD(data)
+	if eocdOffset < 0 {
+		return nil, errMissingEOCD
+	}
+
+	totalEntries := int(binary.LittleEndian.Uint16(data[eocdOffset+10:]))
+	cdSize := int(binary.LittleEndian.Uint32(data[eocdOffset+12:]))
+	cdOffset := int(binary.LittleEndian.Uint32(data[eocdOffset+16:]))
+
+	if cdOffset < 0 || cdOffset+cdSize > len(data) {
+		return nil, errors.New("invalid Zip archive: invalid central directory")
+	}
+
+	entries := make([]zipEntry, 0, totalEntries)
+	cursor := cdOffset
+	for entryIndex := 0; entryIndex < totalEntries; entryIndex++ {
+		if cursor+46 > len(data) {
+			return nil, errors.New("invalid Zip archive: invalid central directory header")
+		}
+		if binary.LittleEndian.Uint32(data[cursor:]) != 0x02014b50 {
+			return nil, errors.New("invalid Zip archive: invalid central directory header")
+		}
+
+		flags := binary.LittleEndian.Uint16(data[cursor+8:])
+		method := binary.LittleEndian.Uint16(data[cursor+10:])
+		modTime := binary.LittleEndian.Uint16(data[cursor+12:])
+		crc := binary.LittleEndian.Uint32(data[cursor+16:])
+		compressedSize := binary.LittleEndian.Uint32(data[cursor+20:])
+		uncompressedSize := binary.LittleEndian.Uint32(data[cursor+24:])
+		nameLen := int(binary.LittleEndian.Uint16(data[cursor+28:]))
+		extraLen := int(binary.LittleEndian.Uint16(data[cursor+30:]))
+		commentLen := int(binary.LittleEndian.Uint16(data[cursor+32:]))
+		localHeaderOffset := binary.LittleEndian.Uint32(data[cursor+42:])
+		bodyStart := cursor + 46
+		bodyEnd := bodyStart + nameLen + extraLen + commentLen
+		if bodyEnd > len(data) {
+			return nil, errors.New("invalid Zip archive: invalid central directory entry")
+		}
+
+		filename := string(data[bodyStart : bodyStart+nameLen])
+		extra := data[bodyStart+nameLen : bodyStart+nameLen+extraLen]
+
+		entry := zipEntry{
+			filename:          filename,
+			flags:             flags,
+			modTime:           modTime,
+			compressionMethod: method,
+			actualCompression: method,
+			crc32:             crc,
+			compressedSize:    compressedSize,
+			uncompressedSize:  uncompressedSize,
+			localHeaderOffset: localHeaderOffset,
+			encrypted:         flags&0x1 != 0,
+		}
+
+		if aes, ok := parseAESExtra(extra); ok {
+			entry.aes = &aes
+			entry.actualCompression = aes.actualCompression
+		}
+
+		dataOffset, offsetErr := findLocalDataOffset(data, localHeaderOffset)
+		if offsetErr != nil {
+			return nil, offsetErr
+		}
+		entry.dataOffset = dataOffset
+
+		entries = append(entries, entry)
+		cursor = bodyEnd
+	}
+
+	return &zipArchive{data: data, entries: entries}, nil
+}
+
+func findEOCD(data []byte) int {
+	start := len(data) - 22
+	if start < 0 {
+		start = 0
+	}
+	minOffset := len(data) - 22 - 65535
+	if minOffset < 0 {
+		minOffset = 0
+	}
+	for idx := start; idx >= minOffset; idx-- {
+		if idx+22 <= len(data) && binary.LittleEndian.Uint32(data[idx:]) == 0x06054b50 {
+			return idx
+		}
+	}
+	return -1
+}
+
+func parseAESExtra(extra []byte) (aesInfo, bool) {
+	cursor := 0
+	for cursor+4 <= len(extra) {
+		headerID := binary.LittleEndian.Uint16(extra[cursor:])
+		fieldLen := int(binary.LittleEndian.Uint16(extra[cursor+2:]))
+		cursor += 4
+		if cursor+fieldLen > len(extra) {
+			return aesInfo{}, false
+		}
+		field := extra[cursor : cursor+fieldLen]
+		cursor += fieldLen
+		if headerID != 0x9901 || len(field) < 7 {
+			continue
+		}
+
+		version := binary.LittleEndian.Uint16(field[0:])
+		strength := field[4]
+		actualCompression := binary.LittleEndian.Uint16(field[5:])
+
+		saltLen := 0
+		keyLen := 0
+		switch strength {
+		case 1:
+			saltLen = 8
+			keyLen = 16
+		case 2:
+			saltLen = 12
+			keyLen = 24
+		case 3:
+			saltLen = 16
+			keyLen = 32
+		default:
+			return aesInfo{}, false
+		}
+
+		return aesInfo{
+			version:           version,
+			strength:          strength,
+			actualCompression: actualCompression,
+			saltLen:           saltLen,
+			keyLen:            keyLen,
+		}, true
+	}
+	return aesInfo{}, false
+}
+
+func findLocalDataOffset(data []byte, localHeaderOffset uint32) (uint64, error) {
+	offset := int(localHeaderOffset)
+	if offset < 0 || offset+30 > len(data) {
+		return 0, errors.New("invalid Zip archive: invalid local file header")
+	}
+	if binary.LittleEndian.Uint32(data[offset:]) != 0x04034b50 {
+		return 0, errors.New("invalid Zip archive: invalid local file header")
+	}
+	nameLen := int(binary.LittleEndian.Uint16(data[offset+26:]))
+	extraLen := int(binary.LittleEndian.Uint16(data[offset+28:]))
+	dataOffset := offset + 30 + nameLen + extraLen
+	if dataOffset > len(data) {
+		return 0, errors.New("invalid Zip archive: invalid local file data")
+	}
+	return uint64(dataOffset), nil
+}
+
+func dictionaryAttack(checker passwordChecker, dictionaryPath string) (string, bool) {
+	file, err := os.Open(dictionaryPath)
+	if err != nil {
+		return "", false
+	}
+	defer file.Close()
+
+	scanner := bufio.NewScanner(file)
+	buffer := make([]byte, 0, 64*1024)
+	scanner.Buffer(buffer, 1024*1024)
+	for scanner.Scan() {
+		candidate := strings.TrimRight(scanner.Text(), "\r")
+		if checker.check(candidate) {
+			return candidate, true
+		}
+	}
+	return "", false
+}
+
+func bruteForceAttack(checker passwordChecker, charset []byte, minLen int, maxLen int, startingPassword string, workers int) (string, bool) {
+	if len(charset) == 0 {
+		return "", false
+	}
+
+	indexMap := make(map[byte]uint64, len(charset))
+	for idx, ch := range charset {
+		if _, exists := indexMap[ch]; !exists {
+			indexMap[ch] = uint64(idx)
+		}
+	}
+
+	startLen := 0
+	startIndex := uint64(0)
+	if startingPassword != "" {
+		startLen = len(startingPassword)
+		startIndex = passwordToIndex(startingPassword, charset, indexMap)
+	}
+
+	for length := minLen; length <= maxLen; length++ {
+		if startLen != 0 && length < startLen {
+			continue
+		}
+
+		lengthStart := uint64(0)
+		if length == startLen {
+			lengthStart = startIndex
+		}
+
+		total, ok := powUint64(uint64(len(charset)), length)
+		if !ok || lengthStart >= total {
+			continue
+		}
+
+		password, found := bruteForceLength(checker, charset, length, lengthStart, total, workers)
+		if found {
+			return password, true
+		}
+	}
+	return "", false
+}
+
+func bruteForceLength(checker passwordChecker, charset []byte, length int, startIndex uint64, total uint64, workers int) (string, bool) {
+	var found atomic.Bool
+	resultCh := make(chan string, 1)
+	var wg sync.WaitGroup
+
+	for worker := 0; worker < workers; worker++ {
+		workerStart := startIndex + uint64(worker)
+		if workerStart >= total {
+			continue
+		}
+		wg.Add(1)
+		go func(first uint64) {
+			defer wg.Done()
+			for idx := first; idx < total; idx += uint64(workers) {
+				if found.Load() {
+					return
+				}
+				candidate := indexToPassword(charset, length, idx)
+				if checker.check(candidate) {
+					if found.CompareAndSwap(false, true) {
+						resultCh <- candidate
+					}
+					return
+				}
+			}
+		}(workerStart)
+	}
+
+	go func() {
+		wg.Wait()
+		close(resultCh)
+	}()
+
+	password, ok := <-resultCh
+	return password, ok
+}
+
+func powUint64(base uint64, exp int) (uint64, bool) {
+	if exp == 0 {
+		return 1, true
+	}
+	result := uint64(1)
+	for i := 0; i < exp; i++ {
+		if base != 0 && result > ^uint64(0)/base {
+			return 0, false
+		}
+		result *= base
+	}
+	return result, true
+}
+
+func passwordToIndex(password string, charset []byte, indexMap map[byte]uint64) uint64 {
+	base := uint64(len(charset))
+	index := uint64(0)
+	for i := 0; i < len(password); i++ {
+		index = index*base + indexMap[password[i]]
+	}
+	return index
+}
+
+func indexToPassword(charset []byte, length int, index uint64) string {
+	base := uint64(len(charset))
+	password := make([]byte, length)
+	for pos := length - 1; pos >= 0; pos-- {
+		password[pos] = charset[index%base]
+		index /= base
+		if pos == 0 {
+			break
+		}
+	}
+	return string(password)
+}
+
+func (checker passwordChecker) check(password string) bool {
+	dataStart := checker.entry.dataOffset
+	dataEnd := dataStart + uint64(checker.entry.compressedSize)
+	if dataEnd > uint64(len(checker.data)) {
+		return false
+	}
+	payload := checker.data[dataStart:dataEnd]
+
+	if checker.entry.aes != nil {
+		return checkAESPassword(checker.entry, payload, password)
+	}
+	return checkZipCryptoPassword(checker.entry, payload, password)
+}
+
+func checkZipCryptoPassword(entry zipEntry, payload []byte, password string) bool {
+	if len(payload) < 12 {
+		return false
+	}
+
+	zc := newZipCrypto([]byte(password))
+	header := make([]byte, 12)
+	for idx := 0; idx < len(header); idx++ {
+		header[idx] = zc.decrypt(payload[idx])
+	}
+
+	verifyByte := byte(entry.crc32 >> 24)
+	if entry.flags&0x8 != 0 {
+		verifyByte = byte(entry.modTime >> 8)
+	}
+	if header[11] != verifyByte {
+		return false
+	}
+
+	encryptedData := payload[12:]
+	decryptedData := make([]byte, len(encryptedData))
+	for idx, ch := range encryptedData {
+		decryptedData[idx] = zc.decrypt(ch)
+	}
+
+	plainData, ok := decompressData(entry.actualCompression, decryptedData)
+	if !ok {
+		return false
+	}
+	if entry.uncompressedSize != uint32(len(plainData)) {
+		return false
+	}
+	return crc32.ChecksumIEEE(plainData) == entry.crc32
+}
+
+func checkAESPassword(entry zipEntry, payload []byte, password string) bool {
+	info := entry.aes
+	if info == nil {
+		return false
+	}
+	minLen := info.saltLen + 2 + 10
+	if len(payload) < minLen {
+		return false
+	}
+
+	salt := payload[:info.saltLen]
+	verifier := payload[info.saltLen : info.saltLen+2]
+	ciphertext := payload[info.saltLen+2 : len(payload)-10]
+	authCode := payload[len(payload)-10:]
+
+	derived := pbkdf2SHA1([]byte(password), salt, 1000, 2*info.keyLen+2)
+	if !bytes.Equal(verifier, derived[2*info.keyLen:]) {
+		return false
+	}
+
+	encryptionKey := derived[:info.keyLen]
+	authenticationKey := derived[info.keyLen : 2*info.keyLen]
+
+	if !validateAESAuth(authenticationKey, ciphertext, authCode) {
+		return false
+	}
+
+	plainCompressed := aesCTRDecrypt(ciphertext, encryptionKey)
+	plainData, ok := decompressData(entry.actualCompression, plainCompressed)
+	if !ok {
+		return false
+	}
+	if entry.uncompressedSize != uint32(len(plainData)) {
+		return false
+	}
+	if entry.crc32 != 0 && crc32.ChecksumIEEE(plainData) != entry.crc32 {
+		return false
+	}
+	return true
+}
+
+func validateAESAuth(key []byte, ciphertext []byte, authCode []byte) bool {
+	mac := hmac.New(sha1.New, key)
+	mac.Write(ciphertext)
+	sum := mac.Sum(nil)
+	return hmac.Equal(authCode, sum[:10])
+}
+
+func pbkdf2SHA1(password []byte, salt []byte, iterations int, keyLen int) []byte {
+	const hLen = 20
+	numBlocks := (keyLen + hLen - 1) / hLen
+	output := make([]byte, 0, numBlocks*hLen)
+
+	var counter [4]byte
+	for block := 1; block <= numBlocks; block++ {
+		binary.BigEndian.PutUint32(counter[:], uint32(block))
+
+		u := hmacSHA1(password, salt, counter[:])
+		t := append([]byte(nil), u...)
+
+		for iteration := 1; iteration < iterations; iteration++ {
+			u = hmacSHA1(password, u)
+			for idx := 0; idx < hLen; idx++ {
+				t[idx] ^= u[idx]
+			}
+		}
+
+		output = append(output, t...)
+	}
+
+	return output[:keyLen]
+}
+
+func hmacSHA1(key []byte, parts ...[]byte) []byte {
+	mac := hmac.New(sha1.New, key)
+	for _, part := range parts {
+		mac.Write(part)
+	}
+	return mac.Sum(nil)
+}
+
+func aesCTRDecrypt(ciphertext []byte, key []byte) []byte {
+	block, err := aes.NewCipher(key)
+	if err != nil {
+		return nil
+	}
+	plaintext := make([]byte, len(ciphertext))
+	var counterBlock [16]byte
+	var streamBlock [16]byte
+	counter := uint32(1)
+
+	for offset := 0; offset < len(ciphertext); offset += aes.BlockSize {
+		for idx := range counterBlock {
+			counterBlock[idx] = 0
+		}
+		binary.LittleEndian.PutUint32(counterBlock[:4], counter)
+		block.Encrypt(streamBlock[:], counterBlock[:])
+
+		remaining := len(ciphertext) - offset
+		blockLen := aes.BlockSize
+		if remaining < blockLen {
+			blockLen = remaining
+		}
+		for idx := 0; idx < blockLen; idx++ {
+			plaintext[offset+idx] = ciphertext[offset+idx] ^ streamBlock[idx]
+		}
+		counter++
+	}
+
+	return plaintext
+}
+
+func decompressData(method uint16, data []byte) ([]byte, bool) {
+	switch method {
+	case 0:
+		return append([]byte(nil), data...), true
+	case 8:
+		reader := flate.NewReader(bytes.NewReader(data))
+		defer reader.Close()
+		out, err := io.ReadAll(reader)
+		if err != nil {
+			return nil, false
+		}
+		return out, true
+	default:
+		return nil, false
+	}
+}
+
+type zipCrypto struct {
+	keys [3]uint32
+}
+
+func newZipCrypto(password []byte) *zipCrypto {
+	zc := &zipCrypto{
+		keys: [3]uint32{0x12345678, 0x23456789, 0x34567890},
+	}
+	for _, ch := range password {
+		zc.updateKeys(ch)
+	}
+	return zc
+}
+
+func (zc *zipCrypto) decrypt(cipherByte byte) byte {
+	plain := cipherByte ^ zc.magicByte()
+	zc.updateKeys(plain)
+	return plain
+}
+
+func (zc *zipCrypto) updateKeys(ch byte) {
+	zc.keys[0] = crc32UpdateByte(zc.keys[0], ch)
+	zc.keys[1] = (zc.keys[1] + uint32(zc.keys[0]&0xff))*134775813 + 1
+	zc.keys[2] = crc32UpdateByte(zc.keys[2], byte(zc.keys[1]>>24))
+}
+
+func (zc *zipCrypto) magicByte() byte {
+	temp := zc.keys[2] | 2
+	return byte((temp * (temp ^ 1)) >> 8)
+}
+
+func crc32UpdateByte(previous uint32, ch byte) uint32 {
+	return crc32.IEEETable[(previous^uint32(ch))&0xff] ^ (previous >> 8)
+}
+
+func formatDuration(duration time.Duration) string {
+	if duration < 0 {
+		duration = 0
+	}
+	totalNs := duration.Nanoseconds()
+	type component struct {
+		value int64
+		unit  string
+	}
+	parts := []component{
+		{value: totalNs / int64(time.Minute), unit: "m"},
+		{value: (totalNs / int64(time.Second)) % 60, unit: "s"},
+		{value: (totalNs / int64(time.Millisecond)) % 1000, unit: "ms"},
+		{value: (totalNs / int64(time.Microsecond)) % 1000, unit: "us"},
+		{value: totalNs % 1000, unit: "ns"},
+	}
+
+	var rendered []string
+	for _, part := range parts {
+		if part.value == 0 && len(rendered) == 0 && part.unit != "ns" {
+			continue
+		}
+		if part.value == 0 && len(rendered) > 0 && part.unit != "ns" {
+			continue
+		}
+		rendered = append(rendered, fmt.Sprintf("%d%s", part.value, part.unit))
+	}
+	if len(rendered) == 0 {
+		return "0ns"
+	}
+	return strings.Join(rendered, " ")
+}
