package main

import (
	"bufio"
	"bytes"
	"compress/flate"
	"crypto/aes"
	"crypto/hmac"
	"crypto/sha1"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

const (
	helpText = `Find the password of protected ZIP files

Usage: executable [OPTIONS] --inputFile <inputFile>

Options:
  -i, --inputFile <inputFile>                    path to zip input file
  -w, --workers <workers>                        number of workers
  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file
  -c, --charset <charset>                        charset to use to generate password [default: lud]
      --charsetFile <charsetFile>                path to a charset file
      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]
      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]
      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]
  -s, --startingPassword <startingPassword>      password to start from
  -h, --help                                     Print help
  -V, --version                                  Print version
`
	versionText = "zip-password-finder 0.10.3"
)

var (
	errMissingEOCD       = errors.New("invalid Zip archive: Could not find EOCD")
	errUnsupportedMethod = errors.New("invalid Zip archive: unsupported compression method")
)

type config struct {
	inputFile          string
	workers            int
	passwordDictionary string
	charset            string
	charsetFile        string
	minPasswordLen     int
	maxPasswordLen     int
	fileNumber         int
	startingPassword   string
	showHelp           bool
	showVersion        bool
}

type zipArchive struct {
	data    []byte
	entries []zipEntry
}

type zipEntry struct {
	filename             string
	flags                uint16
	modTime              uint16
	compressionMethod    uint16
	actualCompression    uint16
	crc32                uint32
	compressedSize       uint32
	uncompressedSize     uint32
	localHeaderOffset    uint32
	dataOffset           uint64
	encrypted            bool
	aes                  *aesInfo
}

type aesInfo struct {
	version           uint16
	strength          uint8
	actualCompression uint16
	saltLen           int
	keyLen            int
}

type passwordChecker struct {
	data  []byte
	entry zipEntry
}

type parseFailure struct {
	message string
	code    int
}

func main() {
	cfg, failure := parseArgs(os.Args[1:])
	if failure != nil {
		printFailure(*failure)
		os.Exit(failure.code)
	}

	if cfg.showHelp {
		fmt.Print(helpText)
		return
	}
	if cfg.showVersion {
		fmt.Println(versionText)
		return
	}

	if err := validateConfig(&cfg); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}

	archive, err := parseZipArchive(cfg.inputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Invalid zip file error - %s\n", err.Error())
		os.Exit(1)
	}

	if cfg.fileNumber < 0 || cfg.fileNumber >= len(archive.entries) {
		fmt.Fprintf(os.Stderr, "File number not found within archive error - '%d'\n", cfg.fileNumber)
		os.Exit(1)
	}

	entry := archive.entries[cfg.fileNumber]
	if !entry.encrypted {
		fmt.Fprintf(
			os.Stderr,
			"Invalid zip file error - the selected file in the archive is not encrypted (file_number:%d file_name:%s)\n",
			cfg.fileNumber,
			entry.filename,
		)
		os.Exit(1)
	}

	charset, err := resolveCharset(cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "CLI argument error - %q\n", err.Error())
		os.Exit(1)
	}

	if err := validateStartingPassword(cfg, charset); err != nil {
		fmt.Fprintf(os.Stderr, "CLI argument error - %q\n", err.Error())
		os.Exit(1)
	}

	checker := passwordChecker{data: archive.data, entry: entry}
	startedAt := time.Now()

	var password string
	var found bool
	if cfg.passwordDictionary != "" {
		password, found = dictionaryAttack(checker, cfg.passwordDictionary)
	} else {
		password, found = bruteForceAttack(checker, charset, cfg.minPasswordLen, cfg.maxPasswordLen, cfg.startingPassword, cfg.workers)
	}

	fmt.Printf("Time elapsed: %s\n", formatDuration(time.Since(startedAt)))
	if found {
		fmt.Printf("Password found:%s\n", password)
		return
	}
	fmt.Println("Password not found")
}

func parseArgs(args []string) (config, *parseFailure) {
	cfg := config{
		charset:        "lud",
		minPasswordLen: 1,
		maxPasswordLen: 10,
		fileNumber:     0,
		workers:        defaultWorkers(),
	}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "-h" || arg == "--help":
			cfg.showHelp = true
		case arg == "-V" || arg == "--version":
			cfg.showVersion = true
		case arg == "-i" || arg == "--inputFile":
			value, next, failure := requireValue(args, i, arg, "inputFile")
			if failure != nil {
				return config{}, failure
			}
			cfg.inputFile = value
			i = next
		case strings.HasPrefix(arg, "--inputFile="):
			cfg.inputFile = strings.TrimPrefix(arg, "--inputFile=")
		case arg == "-w" || arg == "--workers":
			value, next, failure := requireValue(args, i, arg, "workers")
			if failure != nil {
				return config{}, failure
			}
			parsed, parseErr := parseUnsignedValue(value, "--workers <workers>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.workers = parsed
			i = next
		case strings.HasPrefix(arg, "--workers="):
			value := strings.TrimPrefix(arg, "--workers=")
			parsed, parseErr := parseUnsignedValue(value, "--workers <workers>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.workers = parsed
		case arg == "-p" || arg == "--passwordDictionary":
			value, next, failure := requireValue(args, i, arg, "passwordDictionary")
			if failure != nil {
				return config{}, failure
			}
			cfg.passwordDictionary = value
			i = next
		case strings.HasPrefix(arg, "--passwordDictionary="):
			cfg.passwordDictionary = strings.TrimPrefix(arg, "--passwordDictionary=")
		case arg == "-c" || arg == "--charset":
			value, next, failure := requireValue(args, i, arg, "charset")
			if failure != nil {
				return config{}, failure
			}
			cfg.charset = value
			i = next
		case strings.HasPrefix(arg, "--charset="):
			cfg.charset = strings.TrimPrefix(arg, "--charset=")
		case arg == "--charsetFile":
			value, next, failure := requireValue(args, i, arg, "charsetFile")
			if failure != nil {
				return config{}, failure
			}
			cfg.charsetFile = value
			i = next
		case strings.HasPrefix(arg, "--charsetFile="):
			cfg.charsetFile = strings.TrimPrefix(arg, "--charsetFile=")
		case arg == "--minPasswordLen":
			value, next, failure := requireValue(args, i, arg, "minPasswordLen")
			if failure != nil {
				return config{}, failure
			}
			parsed, parseErr := parseUnsignedValue(value, "--minPasswordLen <minPasswordLen>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.minPasswordLen = parsed
			i = next
		case strings.HasPrefix(arg, "--minPasswordLen="):
			value := strings.TrimPrefix(arg, "--minPasswordLen=")
			parsed, parseErr := parseUnsignedValue(value, "--minPasswordLen <minPasswordLen>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.minPasswordLen = parsed
		case arg == "--maxPasswordLen":
			value, next, failure := requireValue(args, i, arg, "maxPasswordLen")
			if failure != nil {
				return config{}, failure
			}
			parsed, parseErr := parseUnsignedValue(value, "--maxPasswordLen <maxPasswordLen>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.maxPasswordLen = parsed
			i = next
		case strings.HasPrefix(arg, "--maxPasswordLen="):
			value := strings.TrimPrefix(arg, "--maxPasswordLen=")
			parsed, parseErr := parseUnsignedValue(value, "--maxPasswordLen <maxPasswordLen>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.maxPasswordLen = parsed
		case arg == "--fileNumber":
			value, next, failure := requireValue(args, i, arg, "fileNumber")
			if failure != nil {
				return config{}, failure
			}
			parsed, parseErr := parseUnsignedValue(value, "--fileNumber <fileNumber>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.fileNumber = parsed
			i = next
		case strings.HasPrefix(arg, "--fileNumber="):
			value := strings.TrimPrefix(arg, "--fileNumber=")
			parsed, parseErr := parseUnsignedValue(value, "--fileNumber <fileNumber>")
			if parseErr != nil {
				return config{}, parseErr
			}
			cfg.fileNumber = parsed
		case arg == "-s" || arg == "--startingPassword":
			value, next, failure := requireValue(args, i, arg, "startingPassword")
			if failure != nil {
				return config{}, failure
			}
			cfg.startingPassword = value
			i = next
		case strings.HasPrefix(arg, "--startingPassword="):
			cfg.startingPassword = strings.TrimPrefix(arg, "--startingPassword=")
		default:
			return config{}, &parseFailure{
				message: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: executable --inputFile <inputFile>\n\nFor more information, try '--help'.", arg),
				code:    2,
			}
		}
	}

	if cfg.showHelp || cfg.showVersion {
		return cfg, nil
	}
	if cfg.inputFile == "" {
		return config{}, &parseFailure{
			message: "error: the following required arguments were not provided:\n  --inputFile <inputFile>\n\nUsage: executable --inputFile <inputFile>\n\nFor more information, try '--help'.",
			code:    2,
		}
	}
	return cfg, nil
}

func requireValue(args []string, currentIndex int, rawArg string, fieldName string) (string, int, *parseFailure) {
	if currentIndex+1 >= len(args) {
		return "", currentIndex, &parseFailure{
			message: fmt.Sprintf("error: a value is required for '%s <%s>' but none was supplied\n\nFor more information, try '--help'.", rawArg, fieldName),
			code:    2,
		}
	}
	return args[currentIndex+1], currentIndex + 1, nil
}

func parseUnsignedValue(raw string, flagLabel string) (int, *parseFailure) {
	if raw == "" {
		return 0, &parseFailure{
			message: fmt.Sprintf("error: invalid value '%s' for '%s': invalid digit found in string\n\nFor more information, try '--help'.", raw, flagLabel),
			code:    2,
		}
	}
	value := 0
	for _, ch := range raw {
