	}
	if cfg.maxPasswordLen < cfg.minPasswordLen {
		return errors.New(`CLI argument error - "'maxPasswordLen' must be equal or greater than 'minPasswordLen'"`)
	}
	if cfg.passwordDictionary != "" && cfg.startingPassword != "" {
