func parseZipArchive(path string) (*zipArchive, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(data) < 22 {
		return nil, errMissingEOCD
	}

	eocdOffset := findEOCD(data)
	if eocdOffset < 0 {
		return nil, errMissingEOCD
	}

	totalEntries := int(binary.LittleEndian.Uint16(data[eocdOffset+10:]))
	cdSize := int(binary.LittleEndian.Uint32(data[eocdOffset+12:]))
	cdOffset := int(binary.LittleEndian.Uint32(data[eocdOffset+16:]))

	if cdOffset < 0 || cdOffset+cdSize > len(data) {
		return nil, errors.New("invalid Zip archive: invalid central directory")
	}

	entries := make([]zipEntry, 0, totalEntries)
	cursor := cdOffset
	for entryIndex := 0; entryIndex < totalEntries; entryIndex++ {
		if cursor+46 > len(data) {
			return nil, errors.New("invalid Zip archive: invalid central directory header")
		}
		if binary.LittleEndian.Uint32(data[cursor:]) != 0x02014b50 {
			return nil, errors.New("invalid Zip archive: invalid central directory header")
		}

		flags := binary.LittleEndian.Uint16(data[cursor+8:])
		method := binary.LittleEndian.Uint16(data[cursor+10:])
		modTime := binary.LittleEndian.Uint16(data[cursor+12:])
		crc := binary.LittleEndian.Uint32(data[cursor+16:])
		compressedSize := binary.LittleEndian.Uint32(data[cursor+20:])
		uncompressedSize := binary.LittleEndian.Uint32(data[cursor+24:])
		nameLen := int(binary.LittleEndian.Uint16(data[cursor+28:]))
		extraLen := int(binary.LittleEndian.Uint16(data[cursor+30:]))
		commentLen := int(binary.LittleEndian.Uint16(data[cursor+32:]))
		localHeaderOffset := binary.LittleEndian.Uint32(data[cursor+42:])
		bodyStart := cursor + 46
		bodyEnd := bodyStart + nameLen + extraLen + commentLen
		if bodyEnd > len(data) {
			return nil, errors.New("invalid Zip archive: invalid central directory entry")
		}

		filename := string(data[bodyStart : bodyStart+nameLen])
		extra := data[bodyStart+nameLen : bodyStart+nameLen+extraLen]

		entry := zipEntry{
			filename:          filename,
			flags:             flags,
			modTime:           modTime,
			compressionMethod: method,
			actualCompression: method,
			crc32:             crc,
			compressedSize:    compressedSize,
			uncompressedSize:  uncompressedSize,
			localHeaderOffset: localHeaderOffset,
			encrypted:         flags&0x1 != 0,
		}

		if aes, ok := parseAESExtra(extra); ok {
			entry.aes = &aes
			entry.actualCompression = aes.actualCompression
		}

		dataOffset, offsetErr := findLocalDataOffset(data, localHeaderOffset)
		if offsetErr != nil {
			return nil, offsetErr
		}
		entry.dataOffset = dataOffset

		entries = append(entries, entry)
		cursor = bodyEnd
	}

	return &zipArchive{data: data, entries: entries}, nil
}

func findEOCD(data []byte) int {
	start := len(data) - 22
	if start < 0 {
		start = 0
	}
	minOffset := len(data) - 22 - 65535
	if minOffset < 0 {
		minOffset = 0
	}
	for idx := start; idx >= minOffset; idx-- {
		if idx+22 <= len(data) && binary.LittleEndian.Uint32(data[idx:]) == 0x06054b50 {
			return idx
		}
	}
	return -1
}

func parseAESExtra(extra []byte) (aesInfo, bool) {
	cursor := 0
	for cursor+4 <= len(extra) {
		headerID := binary.LittleEndian.Uint16(extra[cursor:])
		fieldLen := int(binary.LittleEndian.Uint16(extra[cursor+2:]))
		cursor += 4
		if cursor+fieldLen > len(extra) {
			return aesInfo{}, false
		}
		field := extra[cursor : cursor+fieldLen]
		cursor += fieldLen
		if headerID != 0x9901 || len(field) < 7 {
			continue
		}

		version := binary.LittleEndian.Uint16(field[0:])
		strength := field[4]
		actualCompression := binary.LittleEndian.Uint16(field[5:])

		saltLen := 0
		keyLen := 0
		switch strength {
		case 1:
			saltLen = 8
			keyLen = 16
		case 2:
			saltLen = 12
			keyLen = 24
		case 3:
			saltLen = 16
			keyLen = 32
		default:
			return aesInfo{}, false
		}

		return aesInfo{
			version:           version,
			strength:          strength,
			actualCompression: actualCompression,
			saltLen:           saltLen,
			keyLen:            keyLen,
		}, true
	}
	return aesInfo{}, false
}

func findLocalDataOffset(data []byte, localHeaderOffset uint32) (uint64, error) {
	offset := int(localHeaderOffset)
	if offset < 0 || offset+30 > len(data) {
		return 0, errors.New("invalid Zip archive: invalid local file header")
	}
	if binary.LittleEndian.Uint32(data[offset:]) != 0x04034b50 {
		return 0, errors.New("invalid Zip archive: invalid local file header")
	}
	nameLen := int(binary.LittleEndian.Uint16(data[offset+26:]))
	extraLen := int(binary.LittleEndian.Uint16(data[offset+28:]))
	dataOffset := offset + 30 + nameLen + extraLen
	if dataOffset > len(data) {
		return 0, errors.New("invalid Zip archive: invalid local file data")
	}
	return uint64(dataOffset), nil
}

func dictionaryAttack(checker passwordChecker, dictionaryPath string) (string, bool) {
