func powUint64(base uint64, exp int) (uint64, bool) {
	if exp == 0 {
		return 1, true
	}
	result := uint64(1)
	for i := 0; i < exp; i++ {
		if base != 0 && result > ^uint64(0)/base {
			return 0, false
		}
		result *= base
	}
	return result, true
}

func passwordToIndex(password string, charset []byte, indexMap map[byte]uint64) uint64 {
	base := uint64(len(charset))
	index := uint64(0)
	for i := 0; i < len(password); i++ {
		index = index*base + indexMap[password[i]]
	}
