	if header[11] != verifyByte {
		return false
	}

	encryptedData := payload[12:]
	decryptedData := make([]byte, len(encryptedData))
	for idx, ch := range encryptedData {
		decryptedData[idx] = zc.decrypt(ch)
	}

	plainData, ok := decompressData(entry.actualCompression, decryptedData)
	if !ok {
